#!/usr/bin/env python3
from __future__ import annotations
from datetime import datetime
from pathlib import Path
import base64
import subprocess
import tempfile
import zipfile

ROOT = Path.cwd()
FILES = {
    "app/context/CoinsContext.tsx": "",
    "app/context/UserContext.tsx": "",
    "app/(tabs)/account.tsx": "",
}
NODE_SCRIPT_B64 = ""

class InstallError(RuntimeError):
    pass

def decode_files():
    return {ROOT / rel: base64.b64decode(payload).decode("utf-8") for rel, payload in FILES.items()}

def verify_project():
    required = [ROOT / "package.json", *(ROOT / rel for rel in FILES)]
    missing = [str(path.relative_to(ROOT)) for path in required if not path.is_file()]
    if missing:
        raise InstallError("Run this from the Nova project root. Missing: " + ", ".join(missing))

def syntax_check(contents):
    node_script = base64.b64decode(NODE_SCRIPT_B64).decode("utf-8")
    with tempfile.TemporaryDirectory(prefix="nova-guest-coin-race-") as temp:
        temp_root = Path(temp)
        paths = []
        for index, (original, content) in enumerate(contents.items()):
            target = temp_root / f"{index}-{original.name}"
            target.write_text(content, encoding="utf-8")
            paths.append(str(target))
        result = subprocess.run(["node", "-e", node_script, *paths], cwd=ROOT, text=True, capture_output=True)
        if result.returncode != 0:
            raise InstallError(result.stderr.strip() or result.stdout.strip() or "Syntax check failed")

def make_backup(paths):
    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    directory = ROOT / "backups"
    directory.mkdir(parents=True, exist_ok=True)
    output = directory / f"before_guest_coin_race_fix_{stamp}.zip"
    with zipfile.ZipFile(output, "w", compression=zipfile.ZIP_DEFLATED) as archive:
        for path in paths:
            if path.is_file():
                archive.write(path, path.relative_to(ROOT))
    return output

def main():
    try:
        verify_project()
        contents = decode_files()
        syntax_check(contents)
        backup = make_backup(list(contents.keys()))
        for path, content in contents.items():
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content, encoding="utf-8")
        print("✅ Guest coin sign-out race fixed.")
        print("✅ Sign-out now completes before returning to the guest screen.")
        print("✅ Guest coin writes are blocked during the 8-second reset window.")
        print("✅ The guest wallet is forced to 0 during that reset window.")
        print("✅ Signed-in account balances remain untouched.")
        print("✅ Syntax check passed for all changed files.")
        print(f"✅ Backup: {backup.relative_to(ROOT)}")
        print()
        print("Next: npx expo start --dev-client --clear")
        return 0
    except InstallError as error:
        print("❌ Nothing was written.")
        print("Reason:", error)
        return 1
    except Exception as error:
        print("❌ Nothing was written.")
        print(f"Unexpected error: {type(error).__name__}: {error}")
        return 1

if __name__ == "__main__":
    raise SystemExit(main())
